-- END HANDHELD OPERATIONS
-- One row per route meter. A meter can have several registers (ExpectedChannels); a valid one is a register and its
-- Delta, an Analog register with its own Analog usage point, or a demand read with no register on an Analog point
-- under the meter. ExpectedActive is the meter's enabled
-- flag as configured: Cedar Row C's laundry meter is saved disabled until the Stage 12 route fix.
DECLARE @HmrOperationState TABLE
(
    [Key] nvarchar(128), MeterNumber nvarchar(100), Gateway nvarchar(100), ExpectedCycle nvarchar(2), ExpectedRoute nvarchar(6),
    ExpectedActive bit, ExpectedChannels int,
    MeterID int, HMR_MeterID int, ActualCycle nvarchar(2), ActualRoute nvarchar(6), Active bit,
    ChannelCount int, ValidPairCount int, StoredRegisters int, StoredUsage int, LatestRegisterUtc datetime, LatestUsageUtc datetime
);
INSERT @HmrOperationState
SELECT expected.[Key],expected.MeterNumber,expected.Gateway,expected.Cycle,expected.Route,
    expected.Active,expected.ExpectedChannels,
    meter.MetaWorldID,hmr.HMR_MeterID,hmr.CycleID,hmr.RouteNumber,hmr.active,
    channels.ChannelCount,pairs.ValidPairCount,history.StoredRegisters,history.StoredUsage,history.LatestRegisterUtc,history.LatestUsageUtc
FROM OPENJSON(@HmrOperationsJson,'$.meters') WITH
(
    [Key] nvarchar(128), Company nvarchar(64), MeterNumber nvarchar(100), MeterDescription nvarchar(256),
    Gateway nvarchar(100), Cycle nvarchar(2), Route nvarchar(6), Active bit, ExpectedChannels int
) expected
LEFT JOIN dbo.Company_TBL company ON company.CompanyName=expected.Company
LEFT JOIN dbo.MetaWorld_TBL node ON node.CompanyID=company.CompanyID AND node.Description=expected.MeterDescription AND ISNULL(node.DeleteInd,0)=0
LEFT JOIN dbo.Meter meter ON meter.MetaWorldID=node.MetaWorldID AND meter.SM_Code=expected.MeterNumber
LEFT JOIN dbo.HMR_Meter hmr ON hmr.MetaWorldID=meter.MetaWorldID
OUTER APPLY (SELECT COUNT(*) AS ChannelCount FROM dbo.HMR_Reading r WHERE r.HMR_MeterID=hmr.HMR_MeterID) channels
OUTER APPLY
(
    SELECT COUNT(*) AS ValidPairCount FROM dbo.HMR_Reading r
    JOIN dbo.PointDef_TBL usage ON usage.PtID=r.Ptid_Usage
    JOIN dbo.MetaWorld_TBL usageNode ON usageNode.MetaWorldID=usage.MetaWorldID AND usageNode.ParentID=meter.MetaWorldID
    LEFT JOIN dbo.PointDef_TBL reading ON reading.PtID=r.Ptid_Reading
    LEFT JOIN dbo.MetaWorld_TBL readingNode ON readingNode.MetaWorldID=reading.MetaWorldID
    WHERE r.HMR_MeterID=hmr.HMR_MeterID
      AND ((reading.PtType=3 AND usage.PtType=4 AND readingNode.ParentID=meter.MetaWorldID
            AND EXISTS (SELECT 1 FROM dbo.PtRelatedData_TBL related
                        WHERE related.PtID=reading.PtID AND related.RelatedPtID=usage.PtID AND related.ReasonType=N'D'))
        OR (r.Ptid_Reading IS NULL AND usage.PtType NOT IN (3,4))
        OR (reading.PtType NOT IN (3,4) AND usage.PtType NOT IN (3,4) AND readingNode.ParentID=meter.MetaWorldID
            AND reading.PtID<>usage.PtID))
) pairs
OUTER APPLY
(
    SELECT COUNT(CASE WHEN archive.PtID=r.Ptid_Reading THEN 1 END) AS StoredRegisters,
        COUNT(CASE WHEN archive.PtID=r.Ptid_Usage THEN 1 END) AS StoredUsage,
        MAX(CASE WHEN archive.PtID=r.Ptid_Reading THEN archive.UTCTimeStamp END) AS LatestRegisterUtc,
        MAX(CASE WHEN archive.PtID=r.Ptid_Usage THEN archive.UTCTimeStamp END) AS LatestUsageUtc
    FROM dbo.HMR_Reading r JOIN dbo.AnalogArchive_TBL archive ON archive.PtID IN (r.Ptid_Reading,r.Ptid_Usage)
    WHERE r.HMR_MeterID=hmr.HMR_MeterID
) history;

SELECT expected.Cycle,expected.Route,expected.ExpectedMeters,expected.ExpectedChannels,
    actual.MatchingMeters,actual.ValidChannels,
    CASE WHEN actual.MatchingMeters=expected.ExpectedMeters AND actual.ValidChannels=expected.ExpectedChannels THEN N'PASS' ELSE N'FAIL' END AS Status
FROM OPENJSON(@HmrOperationsJson,'$.routes') WITH
(Cycle nvarchar(2),Route nvarchar(6),ExpectedMeters int,ExpectedChannels int) expected
OUTER APPLY
(
    SELECT COUNT(DISTINCT MeterID) AS MatchingMeters,COALESCE(SUM(ValidPairCount),0) AS ValidChannels
    FROM @HmrOperationState state WHERE state.ExpectedCycle=expected.Cycle AND state.ExpectedRoute=expected.Route
      AND state.ActualCycle=expected.Cycle AND state.ActualRoute=expected.Route AND state.Active=state.ExpectedActive
      AND state.ChannelCount=state.ExpectedChannels
) actual
ORDER BY expected.Cycle,expected.Route;

PRINT '== hmr_history: each permanent meter needs retained register AND usage observations before the operational stage is complete; a configured meter is not collected data. ==';
SELECT MeterNumber,ExpectedCycle AS Cycle,ExpectedRoute AS Route,StoredRegisters,StoredUsage,LatestRegisterUtc,LatestUsageUtc,
    CASE WHEN HMR_MeterID IS NULL THEN N'NOT CONFIGURED'
         WHEN StoredRegisters=0 OR StoredUsage=0 THEN N'NO COMPLETE HISTORY' ELSE N'HISTORY PRESENT - VERIFY ROUND' END AS Status
FROM @HmrOperationState ORDER BY ExpectedCycle,ExpectedRoute,MeterNumber;

PRINT '== hmr_mvrs_events: readings, skips and reader notes for MVRS only. Neptune does not publish this bookkeeping stream. Event rows alone do not prove the corresponding observation is correct. ==';
SELECT state.MeterNumber,log.HMR_Code,COUNT(log.LogID) AS Events,MIN(log.Read_Date) AS FirstReadDate,MAX(log.Read_Date) AS LastReadDate
FROM @HmrOperationState state LEFT JOIN dbo.HMR_Log log ON log.MeterID=state.MeterID
WHERE state.Gateway=N'gw_mvrs_sierra_gas'
GROUP BY state.MeterNumber,log.HMR_Code ORDER BY state.MeterNumber,log.HMR_Code;

PRINT '== hmr_duplicate_events: zero rows expected after an explicit replay of identical MVRS content. ==';
SELECT log.MeterID,log.Read_Date,log.Meter_Reader,log.HMR_Code,log.Meter_Info,log.Log_Text,COUNT(*) AS Copies
FROM dbo.HMR_Log log WHERE EXISTS (SELECT 1 FROM @HmrOperationState state WHERE state.MeterID=log.MeterID AND state.Gateway=N'gw_mvrs_sierra_gas')
GROUP BY log.MeterID,log.Read_Date,log.Meter_Reader,log.HMR_Code,log.Meter_Info,log.Log_Text HAVING COUNT(*)>1;
GO

PRINT '== greenbutton_and_energyai_findings: neither has an entry UI (product backlog items 9 and 10), so every EnergyAI table is empty: EnergyAI_Loads and EnergyAI_Insights 0 ==';
SELECT 'EnergyAI_Loads rows' AS Item, '0' AS Expected, CONVERT(varchar(20), COUNT(*)) AS Actual, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS Result FROM dbo.EnergyAI_Loads
UNION ALL
SELECT 'EnergyAI_Insights rows', '0', CONVERT(varchar(20), COUNT(*)), CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END FROM dbo.EnergyAI_Insights;
GO
